# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# I16A, I16L and LI20 instructions (VLEPEM Rev. 0 Figures A-12, A-13 and
# A-16).  I16A signed fields also accept 0x8000-0xffff, as GNU as does.

# CHECK: e_add2i. 3, 1 # encoding: [0x70,0x03,0x88,0x01]
e_add2i. 3, 1
# CHECK: e_add2i. 3, -1 # encoding: [0x73,0xe3,0x8f,0xff]
e_add2i. 3, -1
# CHECK: e_add2i. 3, -1 # encoding: [0x73,0xe3,0x8f,0xff]
e_add2i. 3, 0xffff
# CHECK: e_add2is 3, 32767 # encoding: [0x71,0xe3,0x97,0xff]
e_add2is 3, 0x7fff
# CHECK: e_cmp16i 3, -32768 # encoding: [0x72,0x03,0x98,0x00]
e_cmp16i 3, -32768
# CHECK: e_mull2i 3, -1 # encoding: [0x73,0xe3,0xa7,0xff]
e_mull2i 3, -1
# CHECK: e_cmpl16i 3, 65535 # encoding: [0x73,0xe3,0xaf,0xff]
e_cmpl16i 3, 0xffff
# CHECK: e_cmph16i 3, -1 # encoding: [0x73,0xe3,0xb7,0xff]
e_cmph16i 3, -1
# CHECK: e_cmphl16i 3, 65535 # encoding: [0x73,0xe3,0xbf,0xff]
e_cmphl16i 3, 0xffff
# CHECK: e_or2i 3, 65535 # encoding: [0x70,0x7f,0xc7,0xff]
e_or2i 3, 0xffff
# CHECK: e_and2i. 3, 65535 # encoding: [0x70,0x7f,0xcf,0xff]
e_and2i. 3, 0xffff
# CHECK: e_or2is 3, 1 # encoding: [0x70,0x60,0xd0,0x01]
e_or2is 3, 1
# CHECK: e_lis 3, 65535 # encoding: [0x70,0x7f,0xe7,0xff]
e_lis 3, 0xffff
# CHECK: e_and2is. 3, 65535 # encoding: [0x70,0x7f,0xef,0xff]
e_and2is. 3, 0xffff
# CHECK: e_li 3, 1 # encoding: [0x70,0x60,0x00,0x01]
e_li 3, 1
# CHECK: e_li 3, -1 # encoding: [0x70,0x7f,0x7f,0xff]
e_li 3, -1
# CHECK: e_li 3, 524287 # encoding: [0x70,0x7f,0x3f,0xff]
e_li 3, 0x7ffff
# CHECK: e_li 3, -524288 # encoding: [0x70,0x60,0x40,0x00]
e_li 3, -0x80000
